import {
  CAR_ICON_BLACK,
  DOCUMENT_O2O_BLACK,
  EXTENDED_WARRANTY_BLACK,
  PAPER_PLANE_BLACK,
  PROPERTY_BLACK,
} from '../../../../../images'
import { checkIsLvAdmin, checkIsLvAgent } from '../../../../../helpers/checkAgentTags'

export const PRODUCT_LIST = [
  {
    code: 'car-protection',
    name: 'Mobil',
    logo: CAR_ICON_BLACK,
    is_active: true,
  },
  {
    code: 'property-protection',
    name: 'Properti',
    logo: PROPERTY_BLACK,
    is_active: true,
  },
  {
    code: 'travel-protection',
    name: 'Perjalanan',
    logo: PAPER_PLANE_BLACK,
    is_active: true,
    tag: 'ANNUAL PLAN',
  },
  {
    code: 'extended-warranty-protection',
    name: 'Extended Warranty',
    logo: EXTENDED_WARRANTY_BLACK,
    is_active: true,
  },
  {
    code: 'offline-to-online-protection',
    name: 'Pesanan Manual',
    logo: DOCUMENT_O2O_BLACK,
    is_active: true,
    tag: 'NEW',
  },
]

export const getProductsList = ({ agentData }) => {
  if (checkIsLvAdmin(agentData)) {
    const disabled = ['offline-to-online-protection']
    return PRODUCT_LIST.filter((v) => !disabled.includes(v.code))
  }
  if (checkIsLvAgent(agentData)) {
    return PRODUCT_LIST
  }
  return []
}
