import { useCallback, useState, useMemo, useRef, forwardRef, useImperativeHandle } from 'react'
import ProviderBranchSection from '../ProviderBranchSection'
import { PkgOptionStyle, PackageBenefitStyle } from './index.style'
import PkgAddonsSection from '../PkgAddonsSection'
import { CustomText } from '../../../../../components'
import CustomCheckbox from '../../../../../components/CustomCheckbox'
import { AgentColorPallette } from '../../../../../configs/colorPallete'
import { Grid } from '../../../../../commonStyle/index.style'
import { LANG_STRINGS } from '../../../../../lang'

function PkgOptionSection ({ pkg = {}, policyData = {}, benefits, onSaveDraft, onHardCopyChange }, parentRef) {
  const pkgAddonsSectionRef = useRef(null)

  const [benefit, showBenefit] = useState(false)
  const [selectedBranch, setSelectedBranch] = useState(policyData?.pkgReqBody?.provider_branch ?? pkg?.provider?.headquarter_branch)
  const [isHardCopySelected, setIsHardCopySelected] = useState(policyData?.applicationData?.hard_copy_required ?? false)
  const isHardCopyRequired = useMemo(() =>
    policyData?.applicationData?.package_data?.always_charge_hard_copy ?? pkg?.always_charge_hard_copy, [policyData, pkg])

  useImperativeHandle(parentRef, () => ({
    getProviderBranch: () => selectedBranch,
    isShowAddonReminderModal: () => pkgAddonsSectionRef.current.isShowAddonReminderModal(),
    showAddonsModal: (show) => pkgAddonsSectionRef.current.showAddonsModal(show)
  }), [selectedBranch, pkgAddonsSectionRef])

  const handleBranchSelect = useCallback((branch) => {
    setSelectedBranch(branch)
    onSaveDraft && onSaveDraft({ provider_branch: branch }, 1)
  }, [onSaveDraft])

  const handleHardCopySelect = useCallback(() => {
    setIsHardCopySelected(prev => {
      const newValue = !prev
      onSaveDraft && onSaveDraft({ hard_copy_required: newValue }, 1)
      onHardCopyChange && onHardCopyChange(newValue)
      return newValue
    })
  }, [onSaveDraft, onHardCopyChange])

  return (
    <PkgOptionStyle>
      <div
        className='accordion-header'
        onClick={() => showBenefit(prev => !prev)}
      >
        <CustomText
          color='#000000'
          size='0.9em'
          bottom='0.5em'
          weight={700}
        >
          Manfaat Utama
        </CustomText>
        <i className={`fas ${benefit ? 'fa-angle-up caret-rotate-down' : 'fa-angle-down caret-rotate-down'}`} />
      </div>
      {
        benefit &&
          <PackageBenefitStyle>
            <CustomText
              color='#000000'
              size='0.85em'
              bottom='0.5em'
              weight={700}
            >
              {benefits[0].title}
            </CustomText>
            <CustomText
              color='#000000'
              size='0.75em'
              bottom='0.5em'
            >
              {benefits[0].description}
            </CustomText>
          </PackageBenefitStyle>
      }
      <ProviderBranchSection
        selectedBranch={selectedBranch}
        onBranchSelect={handleBranchSelect}
        providerCode={pkg?.provider?.code}
      />
      <CustomText
        color={AgentColorPallette.black}
        size='1em'
        top='1.2em'
        bottom='0.5em'
        weight={700}
      >
        {LANG_STRINGS.printPolicy}
      </CustomText>
      <Grid
        gridColumn='10fr 1fr'
        gap='1rem'
        align='center'
        className='margin'
      >
        <CustomText
          color={AgentColorPallette.blackGrey}
          size='0.85rem'
        >
          {LANG_STRINGS.selectThisPolicyIfWantHardCopy}
        </CustomText>
        <CustomCheckbox
          color={AgentColorPallette.black}
          disabled={isHardCopyRequired}
          isChecked={isHardCopyRequired || isHardCopySelected}
          onChange={handleHardCopySelect}
        />
      </Grid>
      <PkgAddonsSection
        ref={pkgAddonsSectionRef}
        pkg={pkg}
        policyData={policyData}
      />
    </PkgOptionStyle>
  )
}

export default forwardRef(PkgOptionSection)
