import { useServiceRequest } from '@pasarpolis/common-react-hooks'
import { useCallback } from 'react'
import { updateDraftQuotesReq } from '../../../../../state/commonState/actions'
import { usePackagesContextValue } from '../../context'
import {
  getPackages, saveAddonsData, getPackagesDetails,
  sendQuotationToCustomer, createApplication, updatePackageStore,
  shareDraftQuoteToCustomerReq
} from '../actions'

export const usePackagesServiceCall = (actionsCall = () => {}) => {
  const [packagesState, dispatch] = usePackagesContextValue()
  const [callApi] = useServiceRequest(dispatch)

  const request = useCallback(async (payload = {}) => {
    await callApi(actionsCall({
      ...payload
    }))
  }, [callApi, actionsCall])

  return [packagesState, request]
}

// get packages
export const useGetPackages = () => usePackagesServiceCall(getPackages)

// get packages details
export const useGetPkgDetail = () => usePackagesServiceCall(getPackagesDetails)

// send quotation to customer
export const useSendQuoteToCustomer = () => usePackagesServiceCall(sendQuotationToCustomer)

// share draft Quote to data
export const useShareDraftQuoteToCustomer = () => usePackagesServiceCall(shareDraftQuoteToCustomerReq)

export const useCreateApplication = () => usePackagesServiceCall(createApplication)

export const useUpdateDraftQuote = () => usePackagesServiceCall(updateDraftQuotesReq)

// update addons data
export const useSaveAddonsData = () => {
  const [{ savedAddonsData }, dispatch] = usePackagesContextValue()
  const addonsRequest = useCallback((payload) => dispatch(saveAddonsData(payload)), [dispatch])
  return [savedAddonsData, addonsRequest]
}

// update package store
export const useUpdatePackageStore = () => {
  const [state, dispatch] = usePackagesContextValue()
  const updatePkgReq = useCallback((payload) => dispatch(updatePackageStore(payload)), [dispatch])
  return [state, updatePkgReq]
}
