import { useCallback, useEffect, useState } from 'react'

export const DISCOUNT_TYPE = {
  NOMINAL: 'nominal',
  PERCENTAGE: 'percentage',
}

// Stable identity so the callbacks/effects below don't re-run every render
// when no handler is supplied.
const noop = () => {}

/**
 * Owns the editable discount state: which input mode is active, the typed
 * value, and whether it breaches the agent's cap. `discountBase` is the amount
 * a percentage is applied to (premium + addons).
 */
export const useDiscountInput = ({
  discount = 0,
  maxDiscount = 0,
  maxDiscountPercent = 0,
  discountBase = 0,
  setDisableBtn = noop,
}) => {
  const [isExpanded, setIsExpanded] = useState(!!discount)
  const [type, setType] = useState(DISCOUNT_TYPE.NOMINAL)
  const [amount, setAmount] = useState(discount)
  const [percent, setPercent] = useState(0)
  const [hasError, setHasError] = useState(false)

  useEffect(() => {
    setAmount(discount)
    setIsExpanded(!!discount)
  }, [discount])

  useEffect(() => {
    const isOverMax = discount > 0 && discount > maxDiscount
    setHasError(isOverMax)
    setDisableBtn(isOverMax)
  }, [discount, maxDiscount, setDisableBtn])

  const toggle = useCallback(() => {
    setIsExpanded((wasExpanded) => {
      if (wasExpanded) {
        setAmount(0)
        setPercent(0)
        setHasError(false)
        setDisableBtn(false)
      }
      return !wasExpanded
    })
  }, [setDisableBtn])

  const changeType = useCallback((nextType) => {
    setType(nextType)
    setAmount(0)
    setPercent(0)
    setHasError(false)
  }, [])

  const handleInputChange = useCallback(
    (event) => {
      // Strip non-numeric characters
      const value = event.target.value.replace(/\D/g, '')
      event.target.value = value

      if (value === '' || value === '0') {
        setAmount(0)
        setPercent(0)
        setHasError(false)
        setDisableBtn(false)
        return
      }

      const isPercentage = type === DISCOUNT_TYPE.PERCENTAGE
      const typedValue = Number(value)
      const nextAmount = isPercentage
        ? Math.floor(discountBase * (typedValue / 100))
        : typedValue
      const isOverMax =
        typedValue > maxDiscount || (isPercentage && typedValue > maxDiscountPercent)

      setAmount(nextAmount)
      setPercent(typedValue)
      setHasError(isOverMax)
      setDisableBtn(isOverMax)
    },
    [type, discountBase, maxDiscount, maxDiscountPercent, setDisableBtn]
  )

  return {
    isExpanded,
    toggle,
    type,
    changeType,
    amount,
    percent,
    hasError,
    handleInputChange,
  }
}
