import { SelectedAddonsStyle, CardBorderStyle, CardItemStyle } from './index.style'
import { useCallback } from 'react'
import { CustomText } from '../../../../../components'
import { AgentColorPallette } from '../../../../../configs/colorPallete'
import AmountTitle from '../../../../../components/AmountTitle'
import { formatMoney } from '../../../../../helpers/utility'
import { Row, DisplayFlexCCC } from '../../../../../commonStyle/index.style'
import moment from 'moment'

function SelectedPkgAddons({ addonsData = [], className, policyDetail }) {
  const currentYear = moment().year()

  const renderAddonsData = useCallback((addonCat) => {
    const addsOn = addonCat?.add_on?.map((addOn) => {
      const isEvVariant = policyDetail?.ev_variant || false
      const ageYears = currentYear - policyDetail?.year
      const brandVariant = isEvVariant ? 'ev_variant' : 'non_ev_variant'

      const brandBaseYearRanges = Object.entries(
        addOn?.percentage?.brand_based_year_ranges || {}
      )?.map(([brand, value]) => ({
        brand,
        data: value,
      }))
      const brandOthersBaseYearData =
        brandBaseYearRanges?.find((item) => item?.brand === 'others')?.data?.[`${brandVariant}`] ||
        {}
      const brandBaseYearData =
        brandBaseYearRanges?.find((item) => item?.brand === policyDetail?.brand_code)?.data?.[
          `${brandVariant}`
        ] || brandOthersBaseYearData

      const awsPercentageKey = Object?.keys(brandBaseYearData)
        ?.map(Number)
        ?.sort((a, b) => a - b)
        ?.find((key) => key >= ageYears)
      const awsPercentage = awsPercentageKey !== undefined ? brandBaseYearData[awsPercentageKey] : 0

      return {
        ...addOn,
        awsPercentage,
      }
    })

    const addonsWithSubtotal = [
      // ...(addonCat.add_on || []),
      ...(addsOn || []),
      {
        add_on_name: 'Subtotal',
        premium: addonCat.add_on?.reduce((sum, item) => sum + (item.premium || 0), 0),
      },
    ]

    return (
      <div className="addons-cat-container" key={addonCat.category_code}>
        <CustomText
          color={AgentColorPallette.black}
          // bgColor={AgentColorPallette.Gray90}
          size="0.75em"
          weight={700}
          bottom="15px"
          className="text-uppercase"
        >
          {addonCat.category_name}
        </CustomText>
        {/* <div className='category-addons'>
          {
            addonCat.add_on.map(addon => (
              <AmountTitle
                title={addon.add_on_name}
                size='0.7em'
                key={addon.add_on_code}
                amount={addon.premium}
              />
            ))
          }
        </div> */}
        {addonsWithSubtotal?.map((item, index) => (
          <CardItemStyle border={index + 1 !== addonsWithSubtotal.length} key={index}>
            <CardBorderStyle border={index + 1 !== addonsWithSubtotal.length}>
              <Row align="center" justify="space-between" gap={item.gap || null}>
                <CustomText
                  color={
                    item.add_on_name === 'Subtotal'
                      ? AgentColorPallette.dodgerBlue
                      : AgentColorPallette.fontGrey
                  }
                  size="12px"
                  weight={700}
                >
                  {item.add_on_name}
                </CustomText>

                <DisplayFlexCCC align="end">
                  <CustomText
                    color={
                      item.add_on_name === 'Subtotal'
                        ? AgentColorPallette.dodgerBlue
                        : AgentColorPallette.regular
                    }
                    size="13px"
                    weight={600}
                    textAlign={item.align || 'left'}
                  >
                    {formatMoney(item.premium, 0)}
                  </CustomText>

                  {item.add_on_name !== 'Subtotal' && item.awsPercentage !== 0 && (
                    <CustomText
                      color={AgentColorPallette.green}
                      size="10px"
                      weight={500}
                      textAlign={item.align || 'left'}
                    >
                      ( {formatMoney(item.sum_insured, 0)} x {item.awsPercentage}% )
                    </CustomText>
                  )}
                </DisplayFlexCCC>

                {/* <CustomText
                    color={item.add_on_name === 'Subtotal' ? AgentColorPallette.dodgerBlue : AgentColorPallette.regular}
                    size='13px'
                    weight={600}
                    textAlign={item.align || 'left'}
                  >
                    {formatMoney(item.premium, 0)}
                  </CustomText> */}
              </Row>
            </CardBorderStyle>
          </CardItemStyle>
        ))}
      </div>
    )
  }, [])

  return (
    <SelectedAddonsStyle className={className}>
      {addonsData?.map((addonCat) => renderAddonsData(addonCat))}
    </SelectedAddonsStyle>
  )
}

export default SelectedPkgAddons
