import { useCallback, useMemo, useState } from 'react'
import { getCreatePolicyQuotationBdy } from '../../../../../helpers/getPackageBody'
import { QUOTATION_EXTRA_KEYS } from '../../../../../constants/quoatation'
import MvPaymentInfo from '../../../../../components/MvPaymentInfo'
import ShareQuotation from '../../../Policy/pages/MVPolicyQuotationPopup'

function PackageActionBtn({
  pkg = {},
  policyData = {},
  history,
  branch,
  onSaveDraft,
  draftId,
  onDiscountChange,
  discountLoader,
  showFinalCommissionWord,
  yearBasedMapping = {},
  isRedirected,
  showDiscountCtn,
  draftQuotationsDetailsData = {},
  isShowAddonReminderModal,
  showAddonsModal,
  onRedirectBackClick,
}) {
  const [showShareSheet, setShowShareSheet] = useState(false)

  const handleShowQuotationModal = useCallback(() => {
    setShowShareSheet(true)
  }, [])

  const getQuotationBody = useCallback(({ discount = 0 }) => {
    let renewalData = {}
    if (pkg?.package_request) {
      renewalData = pkg?.package_request
    }
    return {
      ...policyData.pkgReqBody,
      ...policyData.expiredPolicyData,
      ...getCreatePolicyQuotationBdy({
        policyData: {
          ...policyData.pkgReqBody,
          ...renewalData,
        },
        packageData: pkg,
        discount: discount,  // Use state instead of ref
      }),
    }
  }, [pkg, policyData])

  const handleBuyQuotation = useCallback(
    ({ discount = 0 }) => {
      let body = {
        ...getQuotationBody({ discount }),
      }

      if (policyData.isRenewalFlow) {
        body = {
          ...pkg?.package_request,
          ...policyData.pkgReqBody,
          edit_existing_policy: policyData?.isEditRenewalActionType.AgentColorPallette,
          code: policyData?.code,
          discount: discount, // Use state instead of ref
        }
      }
      body = {
        ...body,
        purchase_type: policyData?.pkgReqBody?.purchase_type,
        provider_branch: branch,
      }
      QUOTATION_EXTRA_KEYS.map((extraKey) => delete body[extraKey])
      onSaveDraft(
        {
          discount: discount, // Use state instead of ref
          package_code: pkg?.package?.code,
          provider_code: pkg?.provider?.code,
          provider_package_code: pkg.code,
        },
        1
      )
    },
    [pkg, policyData, branch, onSaveDraft, getQuotationBody]
  )

  // The premium breakdown reads the draft shape, but the selected package here
  // are newer than what the draft currently holds.
  const policyDetails = useMemo(
    () => ({
      ...draftQuotationsDetailsData?.policy_details,
      package_data: pkg,
    }),
    [draftQuotationsDetailsData, pkg]
  )

  return (
    <>
      <MvPaymentInfo
        policyDetails={policyDetails}
        isDiscountEditable={true}
        onDiscountChange={onDiscountChange}
        onShareClick={handleShowQuotationModal}
        onBuyClick={handleBuyQuotation}
        isRedirected={isRedirected}
        onRedirectBackClick={onRedirectBackClick}
        showDiscountCtn={showDiscountCtn}
        isShowAddonReminderModal={isShowAddonReminderModal}
        showAddonsModal={showAddonsModal}
      />
      {showShareSheet && (
        <ShareQuotation
          draftId={draftId}
          show={showShareSheet}
          onClose={() => setShowShareSheet(false)}
        />
      )}
    </>
  )
}

export default PackageActionBtn
