import { useMemo, useRef, useState, useCallback } from 'react'
import { createPortal } from 'react-dom'
import { get } from 'lodash/object'
import { useLoaderContextValue } from '@pasarpolis/common-react-hooks'
import { Loader } from '../../../../../components'
import PolicyAddons from '../../../../../components/PolicyAddons'
import { LANG_STRINGS } from '../../../../../lang/index'
import Button from '../../../../../components/Button/index'
import BottomActionSheet from '../../../../../components/BottomActionSheet'
import { ButtonContainer, PkgAddonsModalStyle } from './index.style'

function MVPolicyAddonsModal ({
  showModal, onClose, productCode, applicationData,
  onSubmit = () => {}
}) {
  const that = useRef()
  const [isBtnDisable, setBtnDisable] = useState(true)
  const [{ GET_PROVIDER_ADDONS_LOADER, CALCULATE_ADDON_PREMIUM_LOADER }] = useLoaderContextValue()

  const addonsData = useMemo(() => {
    return {
      data: {
        package_type: get(applicationData, 'package.code', ''),
        vehicle_type: get(applicationData, 'policy_detail.vehicle_type', ''),
        brand: get(applicationData, 'policy_detail.brand', ''),
        ev_variant: get(applicationData, 'policy_detail.ev_variant', ''),
        brand_code: get(applicationData, 'policy_detail.brand_code', ''),
        variant: get(applicationData, 'policy_detail.variant', ''),
        variant_code: get(applicationData, 'policy_detail.variant_code', ''),
        additional_sum_insured: get(applicationData, 'policy_detail.additional_sum_insured', ''),
        year: get(applicationData, 'policy_detail.year', ''),
        model: get(applicationData, 'policy_detail.model', ''),
        region_code: get(applicationData, 'policy_detail.region_code', ''),
        vehicle_sum_insured: get(applicationData, 'policy_detail.vehicle_sum_insured', ''),
        vehicle_plate_no: get(applicationData, 'policy_detail.vehicle_plate_no', ''),
        usage: get(applicationData, 'policy_detail.usage', ''),
        start_date: get(applicationData, 'policy_detail.start_date', ''),
        accessories: get(applicationData, 'policy_detail.accessories', ''),
        category_name: get(applicationData, 'policy_detail.category_name', ''),
        purchase_type: get(applicationData, 'policy_detail.purchase_type', ''),
        year_based_package_type_map: get(applicationData, 'policy_detail.year_based_package_type_map', '')
      },
      policyDetail: {
        ...get(applicationData, 'policy_detail', {})
      },
      addons: get(applicationData, 'add_ons', []),
      addonsCategory: get(applicationData, 'add_ons_cat', [])
    }
  }, [applicationData])

  const handleChangesInAddon = useCallback((addonData) => {
    // save the addon data on that ref
    that.current = addonData
    if (isBtnDisable) {
      setBtnDisable(false)
    }
  }, [isBtnDisable])

  const handleSubmit = useCallback(() => {
    onSubmit(that.current)
  }, [onSubmit])

  return createPortal(
    <BottomActionSheet
      onCloseSheet={onClose}
      show={showModal}
      title={LANG_STRINGS.addProtection}
      zIndex={5}
      showHeader
    >
      <PkgAddonsModalStyle>
        <Loader
          visible={GET_PROVIDER_ADDONS_LOADER || CALCULATE_ADDON_PREMIUM_LOADER}
          className='addons-container'
        >
          <PolicyAddons
            productId={productCode}
            data={addonsData}
            onChangeAddon={handleChangesInAddon}
            isMVProduct
          />
          <ButtonContainer>
            <Button
              variant='filled'
              disabled={isBtnDisable}
              onClick={handleSubmit}
            >
              {LANG_STRINGS.saveNew}
            </Button>
          </ButtonContainer>
        </Loader>
      </PkgAddonsModalStyle>
    </BottomActionSheet>,
    document.getElementById('bottom-sheet-portal')
  )
}

export default MVPolicyAddonsModal
