import { forwardRef, useImperativeHandle } from 'react'
import { formatMoney } from '../../helpers/utility'
import { LANG_STRINGS } from '../../lang'
import DiscountEditSection from './DiscountEditSection'
import YearPremium from './YearPremium'
import { buildYearWiseBreakdown, getFees, getDiscount, getTotalBill } from './helpers'
import { useDiscountInput } from './hooks'
import {
  StyleContainer,
  DisplayFlexRow,
  Hr1,
  Hr3,
  TitleLabel,
  SectionLabel,
  PremiumCal,
  TotalPreCal,
  DiscountCal,
} from './index.style'

const MVPremiumBreakdown = forwardRef((props, ref) => {
  const {
    policyDetails,
    isDiscountEditable = false,
    appliedDiscount,
    setDisableBtn,
  } = props

  const yearWiseBreakdown = buildYearWiseBreakdown(policyDetails)
  const fees = getFees(policyDetails)
  const discount = getDiscount(policyDetails, appliedDiscount)
  const totalBill = getTotalBill(policyDetails, appliedDiscount)

  const maxDiscount = policyDetails?.package_data?.max_discount || 0
  const maxDiscountPercent = policyDetails?.package_data?.discount_percentage || 0

  const discountInput = useDiscountInput({
    discount,
    maxDiscount,
    maxDiscountPercent,
    // A percentage discount applies to every premium shown above, addons included
    discountBase: yearWiseBreakdown.reduce((sum, { subTotal }) => sum + subTotal, 0),
    setDisableBtn,
  })

  useImperativeHandle(ref, () => ({
    getDiscountValue: () => discountInput.amount
  }), [discountInput.amount])

  return (
    <StyleContainer>
      <TitleLabel>{'Rincian Transaksi'}</TitleLabel>
      <PremiumCal className="calc-note">
        {'*Total Nilai Pertanggungan'}
      </PremiumCal>
      <br />

      {yearWiseBreakdown.map((yearBreakdown, index) => (
        <YearPremium
          key={`year-${yearBreakdown.year}`}
          {...yearBreakdown}
          defaultOpened={index === 0}
        />
      ))}

      <Hr3 />
      <DisplayFlexRow data-testid="subtotal-transaction-row">
        <TotalPreCal>Total Premi Dasar</TotalPreCal>
        <TotalPreCal>
          {formatMoney(yearWiseBreakdown?.reduce((sum, row) => sum + row.subTotal, 0), 0)}
        </TotalPreCal>
      </DisplayFlexRow>

      <br />
      <SectionLabel>{'Lainnya'}</SectionLabel>
      {fees.map((fee, index) => (
        <div key={fee?.key} data-testid={`fee-row-${fee?.key}`}>
          <DisplayFlexRow>
            <PremiumCal>{fee?.label || ''}</PremiumCal>
            <PremiumCal>{formatMoney(fee?.value, 0)}</PremiumCal>
          </DisplayFlexRow>
          {index !== fees.length - 1 && <Hr1 />}
        </div>
      ))}
      {!!discount && !isDiscountEditable && (
        <>
          <Hr1 />
          <DisplayFlexRow data-testid="discount-row">
            <DiscountCal>{LANG_STRINGS.discount}</DiscountCal>
            <DiscountCal>-{formatMoney(discount, 0, 'Rp')}</DiscountCal>
          </DisplayFlexRow>
        </>
      )}
      {isDiscountEditable && (
        <DiscountEditSection
          discount={discount}
          maxDiscount={maxDiscount}
          maxDiscountPercent={maxDiscountPercent}
          discountInput={discountInput}
        />
      )}

      <Hr3 />
      <DisplayFlexRow data-testid="total-transaction-row">
        <TotalPreCal>Total Transaksi</TotalPreCal>
        <TotalPreCal>{formatMoney(totalBill, 0)}</TotalPreCal>
      </DisplayFlexRow>
    </StyleContainer>
  )
})

export default MVPremiumBreakdown
