/**
 * Shared PopupApi trigger.
 * $compactTrigger: fixed 56px (single-select, or multi with 0–1 resolved value) — matches domestic row height.
 * When multi has chips, grows vertically.
 */
export const InputContainerStyle = styled.div`
  display: flex;
  align-items: center;
  justify-content: space-between;
  border-radius: 12px;
  border: 1px solid
    ${(props) => (props.error ? AgentColorPallette.darkerRed : AgentColorPallette.grey_eee)};
  background: ${AgentColorPallette.white};
  padding-right: 16px;
  box-sizing: border-box;
  cursor: ${(props) => (props.disabled ? 'not-allowed' : 'pointer')};

  ${(props) =>
    props.$compactTrigger
      ? `
    height: 56px;
    min-height: 56px;
  `
      : `
    min-height: 56px;
    height: auto;
  `}

  ${(props) =>
    props.disabled &&
    `
    background-color: ${AgentColorPallette.grey_eee};
    pointer-events: none;
  `}

  .select-content {
    flex: 1;
    padding: 8px 16px 6px;
    display: flex;
    flex-direction: column;
    justify-content: center;
    gap: 4px;
    box-sizing: border-box;
    overflow: hidden;

    ${(props) =>
      props.$compactTrigger
        ? `
      height: 100%;
      min-height: 0;
    `
        : `
      min-height: 56px;
    `}
  }

  /* Reference: small gray label on top, larger bold value below (not floating/shrunk label). */
  .field-label {
    font-size: 10px;
    font-weight: 600;
    color: ${AgentColorPallette.fontGrey};
    display: block;
    line-height: 16px;
    flex-shrink: 0;
  }

  .selected-chip {
    font-size: 12px;
    font-weight: 700;
    line-height: 18px;
    color: ${AgentColorPallette.darkCharcoal};
  }

  .chips-wrap {
    display: flex;
    flex-wrap: wrap;
    gap: 8px;
  }

  .chip {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    background-color: ${AgentColorPallette.darkCharcoal};
    color: ${AgentColorPallette.white};
    border-radius: 8px;
    padding: 6px 10px;
    font-size: 12px;
    font-weight: 700;
    line-height: 16px;
    cursor: pointer;

    .chip-remove {
      font-size: 12px;
      line-height: 1;
      opacity: 0.8;

      &:hover {
        opacity: 1;
      }
    }
  }

  > img {
    width: 16px;
    height: 16px;
    flex-shrink: 0;
  }
`

