// import { useLoaderContextValue } from '@pasarpolis/common-react-hooks'
// hiding custom addns as per product requirement
import { useErrorContextValue, useResetError } from '@pasarpolis/common-react-hooks'
import get from 'lodash/get'
import { Fragment, useCallback, useEffect, useRef, useState, useMemo } from 'react'
import CollapsibleCard from '../../../CollapsibleCard'
import AddonItem from '../../components/AddonItem'
import AddonItemV2 from '../../components/AddonItemV2'
import {
  useCalculateAddonPremium, useGetAllAddons, useGetProviderAddons,
  useResetAddonState, useGetProductPkgAddons
} from '../../state/hooks/usePolicyAddons'
import { PolicyAddonsStyle } from './index.style'
import CustomText from '../../../CustomText'
import { AgentColorPallette } from '../../../../configs/colorPallete'
import { Row } from '../../../../commonStyle/index.style'

function PolicyAddonsContainer (props) {
  const {
    data = {}, onChangeAddon = () => {}, isAllAddons = false, hidePremium = false, preFilledAddons = {},
    // isCustomAddon = false, preFilledCustomAddons = []
    currencyType
  } = props
  // const [{ GET_PROVIDER_ADDONS_LOADER, GET_ALL_ADDONS_LOADER }] = useLoaderContextValue()
  const [{ getProviderAddonsData = [] }, getProviderAddonsRequest] = useGetProviderAddons()
  const [, getAllAddonsRequest] = useGetAllAddons()
  const [, getProductPkgAddonsReq] = useGetProductPkgAddons()
  const resetAddonState = useResetAddonState()
  const [{ calculateAddonPremiumData = {} }, getCalculateAddonPremiumRequest] = useCalculateAddonPremium()
  const [{ calculateAddonPremiumStatus }] = useErrorContextValue()
  const { resetError } = useResetError()

  const preSelectedAddons = useMemo(() => {
    const addonsMap = {}
    if (data.addonsCategory && data.addonsCategory.length) {
      data.addonsCategory.forEach(addons => {
        addonsMap[addons.category_name] = {}
        addons.add_on.forEach(addon => {
          const addonItemMap = {}
          if (addon.add_on_code === 'driver-insurance') {
            addonItemMap[addon.add_on_code] = {
              ...addon,
              limit: get(data.policyDetail, 'driver_sum_insured', 0)
            }
          } else if (addon.add_on_code === 'passenger-insurance') {
            addonItemMap[addon.add_on_code] = {
              ...addon,
              no_passanger: get(data.policyDetail, 'no_of_pax', 0),
              premium: addon.premium / get(data.policyDetail, 'no_of_pax', 0),
              limit: get(data.policyDetail, 'passenger_sum_insured_pax', 0)
            }
          } else {
            addonItemMap[addon.add_on_code] = {
              ...addon,
              limit: get(data.policyDetail, `${addon.add_on_code.replace(/-/g, '_')}_sum_insured`, 0)
            }
          }
          addonsMap[addons.category_name] = {
            ...addonsMap[addons.category_name],
            ...addonItemMap
          }
        })
      })
    }
    return Object.keys(preFilledAddons).length ? preFilledAddons : addonsMap
  }, [data.addonsCategory, data.policyDetail, preFilledAddons])

  const [addonsState, setAddonsState] = useState(preSelectedAddons)
  const that = useRef({
    selectedAddons: {},
    isCallAddons: false
  })

  useEffect(() => {
    if (!that.current.isCallAddons) {
      that.current.isCallAddons = true
      if (isAllAddons) {
        getAllAddonsRequest({
          productCode: props.productId
        })
      } else if (props.isProductAddons) {
        getProductPkgAddonsReq({
          body: data.data,
          productCode: props.productId
        })
      } else {
        getProviderAddonsRequest({
          productId: props.productId,
          body: data.data
        })
      }
    }
  }, [
    getProviderAddonsRequest, getProductPkgAddonsReq,
    props, data.data, isAllAddons, getAllAddonsRequest
  ])

  useEffect(() => {
    if ((calculateAddonPremiumStatus === 'success') && calculateAddonPremiumData && that.current.premiumCalculationAddon) {
      const addonCategoryName = that.current.premiumCalculationAddon.addons.category_name
      const addonCode = that.current.premiumCalculationAddon.addon.add_on_code
      const addon = {
        ...that.current.premiumCalculationAddon.addon
      }
      that.current.premiumCalculationAddon = undefined
      setAddonsState(addonState => {
        const addonCategory = addonState[addonCategoryName]
        addonCategory[addonCode] = {
          ...addon
        }
        addonCategory[addonCode].premium = calculateAddonPremiumData.premium
        const modifiedState = {
          ...addonState,
          [addonCategoryName]: {
            ...addonCategory
          }
        }
        onChangeAddon(modifiedState)
        return {
          ...modifiedState
        }
      })
      resetAddonState({
        calculateAddonPremiumData: {}
      })
      resetError(['calculateAddonPremiumStatus'])
    }
  }, [
    calculateAddonPremiumData, resetAddonState, resetError,
    onChangeAddon, calculateAddonPremiumStatus
  ])

  const handleSelectedItem = useCallback((addons, addonItem, actionType) => {
    // handle the selected item here on basis of actionType
    if (actionType === 'add') {
      // if items are added then add then in the store
      // store the item in the local store
      setAddonsState(addonsState => {
        const addonCategory = addonsState[addons.category_name] || {}
        const modified = {
          ...addonsState,
          [addons.category_name]: {
            ...addonCategory,
            [addonItem.add_on_code]: {
              ...addonItem
            }
          }
        }
        onChangeAddon(modified)
        return modified
      })
    } else {
      // this means remove the items from the local store
      setAddonsState(addonsState => {
        const addonCategory = addonsState[addons.category_name]
        delete addonCategory[addonItem.add_on_code]
        // if the remove addon is driver-insurance then also remove passenger insurance
        // addon from the addonState
        if ((addonItem.add_on_code === 'driver-insurance') && addonCategory['passenger-insurance']) {
          delete addonCategory['passenger-insurance']
        }
        if (addonCategory && !Object.keys(addonCategory).length) {
          delete addonsState[addons.category_name]
        } else {
          addonsState[addons.category_name] = {
            ...addonCategory
          }
        }
        onChangeAddon(addonsState)
        return {
          ...addonsState
        }
      })
    }
  }, [onChangeAddon])

  const handleCalculatePremium = useCallback((addons, addon) => {
    that.current.premiumCalculationAddon = {
      addons,
      addon
    }
    if (addon.calc_method === 'p_calc') {
      getCalculateAddonPremiumRequest({
        productCode: 'car-protection', // this is the product code
        body: {
          provider_package_map_code: props.productId,
          addon_code: addon.add_on_code,
          addon_count: 1,
          sum_insured: addon.value,
          vehicle_sum_insured: get(data.data, 'vehicle_sum_insured', ''),
          purchase_type: 'new-purchase',
          package_type: get(data.data, 'package_type', ''),
          variant: get(data.data, 'variant', ''),
          variant_code: get(data.data, 'variant_code', ''),
          year: get(data.data, 'year', ''),
          usage: get(data.data, 'usage', ''),
          vehicle_type: get(data.data, 'vehicle_type', ''),
          start_date: get(data.data, 'start_date', ''),
          region_code: get(data.data, 'region_code', ''),
          category_name: get(data.data, 'category_name', ''),
          brand: get(data.data, 'brand', ''),
          brand_code: get(data.data, 'brand_code', ''),
          ev_variant: get(data.data, 'ev_variant', ''),
          year_based_package_type_map: get(data.data, 'year_based_package_type_map', '')
        }
      })
    } else {
      // handle the user premium here
      const addonCategoryName = that.current.premiumCalculationAddon.addons.category_name
      const addonCode = that.current.premiumCalculationAddon.addon.add_on_code
      that.current.premiumCalculationAddon = undefined
      setAddonsState(addonState => {
        const addonCategory = addonState[addonCategoryName]
        addonCategory[addonCode] = {
          ...addonCategory[addonCode],
          ...addon
        }
        const modifiedState = {
          ...addonState,
          [addonCategoryName]: {
            ...addonCategory
          }
        }
        onChangeAddon(modifiedState)
        return {
          ...modifiedState
        }
      })
    }
  }, [getCalculateAddonPremiumRequest, data.data, onChangeAddon, props.productId])

  const getCheckedAddonsCount = useCallback((categoryName) => {
    const categoryAddons = addonsState[categoryName] || {}
    return Object.keys(categoryAddons).length
  }, [addonsState])

  // const handleCustomAddonAdd = useCallback((customAddon) => {
  //   const addonsMap = {
  //     custom_add_on: customAddon
  //   }
  //   onChangeAddon(addonsMap)
  // }, [onChangeAddon])

  const addonList = getProviderAddonsData?.[0]?.unique_addons_list ?? getProviderAddonsData ?? []
  return (
    <PolicyAddonsStyle>
      {
        !!getProviderAddonsData.length && (
          addonList?.map((addons) => {
            if (props.isAddonV2) {
              return (
                <AddonItemV2
                  addonCategory={addons}
                  addonsState={addonsState}
                  hidePremium={hidePremium}
                  onSelectedItem={handleSelectedItem}
                  onCalculatePremium={handleCalculatePremium}
                />
              )
            }
            const checkedCount = getCheckedAddonsCount(addons.category_name)
            return (
              <CollapsibleCard
                title={
                  <Row align='center'>
                    <CustomText color={AgentColorPallette.blackGrey} weight={800} size='14px'>
                      {addons.category_name}
                    </CustomText>
                    {checkedCount > 0 && (
                      <CustomText color='#0078FA' weight={800} padLeft='4px' size='14px'>
                        ({checkedCount})
                      </CustomText>
                    )}
                  </Row>
                }
                isOpen
                key={addons.category_code}
                className='card_addons'
              >
                {
                  addons.add_on.map((item, index) => {
                    if (!get(addonsState[addons.category_name], 'driver-insurance', '') && item.add_on_code === 'passenger-insurance') return null
                    return (
                      <Fragment key={item.add_on_code}>
                        <AddonItem
                          item={item}
                          hidePremium={hidePremium}
                          currencyType={currencyType}
                          selectedItem={addonsState[addons.category_name] && addonsState[addons.category_name][item.add_on_code]}
                          onSelectItem={(addonItem, actionType) => handleSelectedItem(addons, addonItem, actionType)}
                          onPremiumCalculation={(addon) => handleCalculatePremium(addons, addon)}
                        />
                        {
                          (index + 1 !== addons.add_on.length) && <div className='space' />
                        }
                      </Fragment>
                    )
                  })
                }
              </CollapsibleCard>
            )
          })
        )
      }

    </PolicyAddonsStyle>
  )
}

export default PolicyAddonsContainer
