import { createContext, useCallback, useContext, useReducer } from 'react'
import reducer, { INITIAL_STATE } from './state/reducers'
import { setContextStateAction, resetContextStateAction } from './state/actions'

// this is the context used by the all pages
export const DynamicPurchaseFlowContext = createContext()

// provider provide the update context value
export const DynamicPurchaseFlowContextProvider = (props) => {
  // use reducer provides the initial state and dispatch function
  // to all nested children [state, dispatch]
  const [state, dispatch] = useReducer(reducer, INITIAL_STATE)

  const setContextState = useCallback((payload) => dispatch(setContextStateAction(payload)), [])

  const dispatchResetContextState = useCallback(
    (payload) => dispatch(resetContextStateAction(payload)),
    []
  )

  const ctxValue = [state, dispatch, setContextState, dispatchResetContextState]
  return (
    <DynamicPurchaseFlowContext.Provider value={ctxValue}>
      {props.children}
    </DynamicPurchaseFlowContext.Provider>
  )
}

// use to read the value from the global state
export const useDynamicPurchaseFlowContext = () => useContext(DynamicPurchaseFlowContext)
