import CustomCollapse from '../../components/CustomCollapse'
import { AgentColorPallette } from '../../configs/colorPallete'
import { formatMoney } from '../../helpers/utility'
import { getCalcLabel } from './helpers'
import {
  DisplayFlexRow,
  Hr1,
  Hr2,
  SectionLabel,
  PremiumCal,
} from './index.style'

const YearPremium = ({ year, title, rows, subTotal, defaultOpened }) => (
  <div className="year-section" data-testid={`premium-breakdown-year-${year}`}>
    <CustomCollapse
      label={title}
      labelColor={AgentColorPallette.darkCharcoal}
      isOpened={defaultOpened}
      hideBorders
      noPadding
    >
      {rows.map((row, index) => {
        const calcLabel = getCalcLabel(row)
        return (
          <div key={row.key} data-testid={`premium-row-${row.key}`}>
            <DisplayFlexRow>
              <div className="row-label">
                <PremiumCal>{row.label}</PremiumCal>
                {calcLabel && <PremiumCal className="calc-note">{calcLabel}</PremiumCal>}
              </div>
              <PremiumCal>{formatMoney(row.premium, 0, 'Rp')}</PremiumCal>
            </DisplayFlexRow>
            {index < rows.length - 1 && <Hr1 />}
          </div>
        )
      })}
    </CustomCollapse>
    <Hr2 />
    <DisplayFlexRow className="sub-total-row">
      <SectionLabel>{'Sub Total'}</SectionLabel>
      <PremiumCal>{formatMoney(subTotal, 0, 'Rp')}</PremiumCal>
    </DisplayFlexRow>
  </div>
)

export default YearPremium
