import { CustomText } from '..'
import ConfirmationModalV2 from '../ConfirmationModalV2'
import { LANG_STRINGS } from '../../lang/index'
import { AgentColorPallette } from '../../configs/colorPallete'
import ShowSnackbar from '../ShowNotification'
import { useHistory } from 'react-router-dom'
import { gTagOnSaveDraftQuoteClose } from '../../containers/Private/Policy/gTag'

function QuoteSaveConfirmModal ({ show, onClose = () => {}, page, message }) {
  const history = useHistory()

  return (
    <ConfirmationModalV2
      okText={LANG_STRINGS.yesOk}
      cancelText={LANG_STRINGS.back}
      title={LANG_STRINGS.closeQuoteCreation}
      cancelButtonColor={AgentColorPallette.goldenText}
      okButtonColor={AgentColorPallette.goldenText}
      onCancel={onClose}
      onOk={() => {
        history.replace('/dashboard')
        if (message) {
          ShowSnackbar.success({
            visible: true,
            text: message
          })
        }
        gTagOnSaveDraftQuoteClose(page)
      }}
      visible={show}
    >
      <CustomText
        size='1.2em'
        color={AgentColorPallette.darkCharcoal}
        bottom='1.5rem'
      >
        {LANG_STRINGS.doYouWantToCloseQuoteProcess}
      </CustomText>
      <CustomText
        size='0.7em'
        color={AgentColorPallette.darkCharcoal}
      >
        {LANG_STRINGS.note}:
      </CustomText>
      <CustomText
        size='0.6m'
        color={AgentColorPallette.darkCharcoal}
      >
        {LANG_STRINGS.savedDraftQuoteNotes}
      </CustomText>
    </ConfirmationModalV2>
  )
}

export default QuoteSaveConfirmModal
