import { getFileExtension } from '../utility'

(function () {
  if (window) {
    window.downloadFile = downloadFile
  }
})()

function isIos () {
  const userAgent = window.navigator.userAgent.toLowerCase()
  return /iphone|ipad|ipod/.test(userAgent)
}

/* Helper function */
function downloadPdfAnchor (fileURL) {
  // for non-IE
  if (!window.ActiveXObject) {
    var save = document.createElement('a')
    save.href = fileURL
    save.target = '_blank'
    var filename = fileURL.substring(fileURL.lastIndexOf('/') + 1)
    save.download = filename || 'Policy'
    if (navigator.userAgent.toLowerCase().match(/(ipad|iphone|safari)/) && navigator.userAgent.search('Chrome') < 0) {
      document.location = save.href
      // window event not working here
    } else {
      window.open(fileURL, '_blank')
    }
  } else if (!!window.ActiveXObject && document.execCommand) {
    var _window = window.open(fileURL, '_blank')
    _window.document.close()
    _window.document.execCommand('SaveAs', true, 'Policy' || fileURL)
    _window.close()
  }
}

function downloadFileByFetch (pdfUrl) {
  if (getFileExtension(pdfUrl) !== 'pdf') {
    return downloadPdfAnchor(pdfUrl)
  }
  fetch(pdfUrl, {
    method: 'GET'
  }).then(function (response) {
    if (!response.ok) {
      // this automatically try to download by pdf
      throw new Error('Network response was not ok')
    }
    return response.blob()
  }).then(function (resp) {
    // set the blog type to final pdf
    const file = new Blob([resp], { type: 'application/pdf' })
    // process to auto download it
    const fileURL = URL.createObjectURL(file)
    const link = document.createElement('a')
    link.href = fileURL
    link.download = 'Documents' + Date.now()
    link.click()
  }).catch(function (e) {
    downloadPdfAnchor(pdfUrl)
    return { error: e }
  })
}

export function downloadFile (url, fileName, callback) {
  // url is file path, that need to download on android and iOS device
  // callback that need to be called after fill download
  try {
    if (window.PPBridge) {
      // this returns the version code for the app
      window.PPBridge.downloadFile(url, fileName)
      return true
    } else if (isIos() && window.webkit) {
      window.response = function () {
        // const msg = JSON.stringify(bridgeMsg)
        // const obj = JSON.parse(msg)
        if (callback) {
          callback()
        }
      }
      window.webkit.messageHandlers.callbackHandler.postMessage({
        method: 'downloadFile',
        url: url,
        fileName: fileName
      })
    } else {
      downloadFileByFetch(url)
    }
    if (callback) {
      callback()
    }
  } catch (error) {
    // if this not exist then show error
    if (callback) {
      callback()
    }
    return error
  }
}
