import { ADDONS_ACTIONS } from './actions'

export const INITIAL_STATE = {

}

const reducer = (state = INITIAL_STATE, action = {}) => {
  const { type, payload = {} } = action
  switch (type) {
    case ADDONS_ACTIONS.GET_ADDONS:
    case ADDONS_ACTIONS.GET_PROVIDER_ADDONS:
    case ADDONS_ACTIONS.CALCULATE_ADDON_PREMIUM:
    case ADDONS_ACTIONS.RESET_ADDON_STATE:
      return {
        ...state,
        ...payload
      }
    case ADDONS_ACTIONS.GET_ALL_ADDONS:
      return {
        ...state,
        getProviderAddonsData: payload.getAllAddonsData
      }
    case ADDONS_ACTIONS.GET_PRODUCT_PKG_ADDONS:
      return {
        ...state,
        getProviderAddonsData: payload.getProductPkgAddonsData
      }
    default:
      return {
        ...(state || {})
      }
  }
}

export default reducer
