import { useCallback, useState } from 'react'
import { AgentColorPallette } from '../../../../configs/colorPallete'
import { formatMoney } from '../../../../helpers/utility'
import CustomCheckbox from '../../../CustomCheckbox'
import CustomText from '../../../CustomText'
import { PropertyAddonItemStyle, AddonTitlePriceStyle } from './index.style'

function PropertyAddonItem (props) {
  const {
    item = {}, selectedItem = {}, onSelectItem
  } = props

  const [checked, setChecked] = useState(selectedItem.add_on_code === item.add_on_code)

  const handleChangeCheckbox = useCallback((item) => {
    setChecked(checked => {
      onSelectItem(item, !checked ? 'add' : 'remove')
      return !checked
    })
  }, [onSelectItem])

  return (
    <PropertyAddonItemStyle>
      <AddonTitlePriceStyle
        className='cursor'
        onClick={() => handleChangeCheckbox(item)}
      >
        <CustomCheckbox
          isChecked={checked}
          color={AgentColorPallette.regular}
          onChange={(e) => {
            e.stopPropagation()
            handleChangeCheckbox(item)
          }}
          name={`addonCheckbox-${item.add_on_code}`}
          id={`addonCheckbox-${item.add_on_code}`}
        />
        <div>
          <CustomText
            color={AgentColorPallette.regular}
            weight={800}
          >
            {item.add_on_name}
          </CustomText>
          <CustomText
            size='10px'
            color={AgentColorPallette.fontSemiGrey}
            top='0'
            weight={700}
          >
            {formatMoney(item.premium, 0, 'Biaya tambahan Rp ')}
          </CustomText>
        </div>
      </AddonTitlePriceStyle>
      {
        !!item.extra_details.length && (
          <ul>
            {
              item.extra_details.map((extraItem, index) => (
                <li className='extra-item' key={`extra-item-${index}`}>
                  {extraItem}
                </li>)
              )
            }
          </ul>
        )
      }
    </PropertyAddonItemStyle>
  )
}

export default PropertyAddonItem
