import { forwardRef, useCallback } from 'react'
import BottomActionSheet from '../../../BottomActionSheet'
import { LANG_STRINGS } from '../../../../lang/index'
import MVPremiumBreakdown from '../../../MVPremiumBreakdown'
import { AgentColorPallette } from '../../../../configs/colorPallete'
import { PaymentContainer } from './index.style'

const PaymentBottomSheet = forwardRef((props, parentRef) => {
  const {
    show,
    onClose,
    policyDetails,
    isDiscountEditable,
    appliedDiscount,
    loader = false,
    setDisableBtn = () => {},
  } = props

  const handleClose = useCallback(() => {
    // Reset button state before closing
    setDisableBtn(false)
    onClose()
  }, [onClose, setDisableBtn])

  return (
    <BottomActionSheet
      loader={loader}
      show={show}
      showHeader
      title={LANG_STRINGS.transactionDetail}
      backGroundColor={AgentColorPallette.primary}
      maxHeight="calc(100% - 100px)"
      bottom="58px"
      onCloseSheet={handleClose}
    >
      <PaymentContainer>
        <MVPremiumBreakdown
          ref={parentRef}
          policyDetails={policyDetails}
          isDiscountEditable={isDiscountEditable}
          discount={appliedDiscount}
          setDisableBtn={setDisableBtn}
        />
      </PaymentContainer>
    </BottomActionSheet>
  )
})

export default PaymentBottomSheet
