import { ConfigUrl } from '../../../configs/url'

export const ADDONS_ACTIONS = {
  GET_ADDONS_REQUEST: 'GET_ADDONS_REQUEST',
  GET_ADDONS: 'GET_ADDONS',

  GET_PROVIDER_ADDONS_REQUEST: 'GET_PROVIDER_ADDONS_REQUEST',
  GET_PROVIDER_ADDONS: 'GET_PROVIDER_ADDONS',

  GET_ALL_ADDONS_REQUEST: 'GET_ALL_ADDONS_REQUEST',
  GET_ALL_ADDONS: 'GET_ALL_ADDONS',

  GET_PRODUCT_PKG_ADDONS_REQUEST: 'GET_PRODUCT_PKG_ADDONS_REQUEST',
  GET_PRODUCT_PKG_ADDONS: 'GET_PRODUCT_PKG_ADDONS',

  CALCULATE_ADDON_PREMIUM_REQUEST: 'CALCULATE_ADDON_PREMIUM_REQUEST',
  CALCULATE_ADDON_PREMIUM: 'CALCULATE_ADDON_PREMIUM',

  RESET_ADDON_STATE: 'RESET_ADDON_STATE'
}

export const getAddonsData = (payload = {}) => ({
  type: ADDONS_ACTIONS.GET_ADDONS_REQUEST,
  payload: {
    ...payload,
    method: 'POST',
    url: ConfigUrl.getAddonsApi(payload.productId)
  }
})

export const getProviderAddons = (payload = {}) => ({
  type: ADDONS_ACTIONS.GET_PROVIDER_ADDONS_REQUEST,
  payload: {
    ...payload,
    method: 'POST',
    url: ConfigUrl.providerAddonsApi(payload.productId)
  }
})

export const getAllAddonsData = (payload = {}) => ({
  type: ADDONS_ACTIONS.GET_ALL_ADDONS_REQUEST,
  payload: {
    ...payload,
    method: 'GET',
    url: ConfigUrl.getAllAddonsApi(payload.productCode)
  }
})

export const getProductPkgAddonsReq = (payload = {}) => ({
  type: ADDONS_ACTIONS.GET_ALL_ADDONS_REQUEST,
  payload: {
    ...payload,
    method: 'POST',
    url: ConfigUrl.getAddonsApi(payload.productCode)
  }
})

export const getCalculatedAddonPremium = (payload = {}) => ({
  type: ADDONS_ACTIONS.CALCULATE_ADDON_PREMIUM_REQUEST,
  payload: {
    ...payload,
    method: 'POST',
    url: ConfigUrl.calculateAddonPremium(payload.productCode)
  }
})

export const resetAddonState = (payload) => ({
  type: ADDONS_ACTIONS.RESET_ADDON_STATE,
  payload
})
