import { RadioV2Style } from './index.style'
import { useState, useCallback } from 'react'

function RadioV2({
  data = [],
  name,
  defaultValue,
  className,
  direction = 'vertical',
  titleSize,
  onChange,
}) {
  const [selected, setSelected] = useState(defaultValue)

  const handleChange = useCallback(
    (value) => {
      setSelected(value)
      onChange(value)
    },
    [onChange]
  )

  return (
    <RadioV2Style className={className} direction={direction} titleSize={titleSize}>
      {data.map((item) => (
        <label className="radio-container" key={item.value}>
          {item.name}
          <input
            type="radio"
            checked={selected === item.value}
            name={name}
            value={item.value}
            onChange={(e) => handleChange(item.value)}
          />
          <span className="checkmark" />
        </label>
      ))}
    </RadioV2Style>
  )
}

export default RadioV2
