import {
  updateLoader,
  useErrorContextValue,
  useLoaderContextValue,
  useResetError,
} from '@pasarpolis/common-react-hooks'
import { useCallback, useEffect, useRef, useState } from 'react'
import { Container } from '../../../../../../components'
import PolicyStepsHeader from '../../../../../../components/PolicyStepsHeader'
import Tabs from '../../../../../../components/Tabs'
import { POLICY_PKG_DATA } from '../../../../../../constants/cookies'
import {
  getAddonsMapFromCategory,
  getExtraVehicleData,
  getPackagesReqBody,
} from '../../../../../../helpers/getPackageBody'
import { getFromLocalStorageData, setToLocalStorage } from '../../../../../../helpers/localstorage'
import PackageItem from '../../../../Application/components/PackageItem'
import { POLICY_STEPS } from '../../../../Policy/constants'
import {
  useGetPkgDetail,
  useSaveAddonsData,
  useUpdateDraftQuote,
} from '../../../state/hooks/usePackages'
import { PackageDetailsStyle } from './index.style'
import { PKG_DETAILS_TAB } from '../../../constants/index'
import PkgOptionSection from '../../../components/PkgOptionSection'
import PackageBenefitSection from '../../../components/PackageBenefitSection'
import PackageTermsSection from '../../../components/PackageTermsSection'
import PackageActionBtn from '../../../components/PackageActionBtn'
import { useHistory } from 'react-router-dom'
import moment from 'moment'
import { LANG_STRINGS } from '../../../../../../lang'
import QuoteSaveConfirmModal from '../../../../../../components/QuoteSaveConfirmModal'
import { useGetDraftQuoteDetails } from '../../../../Policy/state/hooks/usePolicyState'
import { checkValidateStartDate, getQueryParams } from '../../../../../../helpers/utility'
import { useParams } from 'react-router'
import { useBackButton } from '../../../../../../state/commonState/hooks/useBackButton'
import ShowSnackbar from '../../../../../../components/ShowNotification'
import PackageNotFound from '../../../components/PackageNotFound'
import { CAR_PROTECTION } from '../../../../../../constants/pkgCode'

function PackageDetailsContainer(props) {
  const { draftQuoteId } = useParams()
  const {
    activeTab: currActiveTab = 0,
    isRedirected = false,
    redirectBackUrl,
    showDiscountCtn = true,
  } = props.location?.state || {}

  const [{ getPackageDetailData = {} }, getPkgDetailsReq] = useGetPkgDetail()
  const [savedAddonsData] = useSaveAddonsData()
  const [enableSave, setEnableSave] = useState(false)
  const [showQuoteConfirm, setShowQuoteConfirm] = useState(false)
  const [
    {
      GET_PACKAGE_DETAIL_LOADER,
      CREATE_APPLICATION_LOADER,
      UPDATE_DRAFT_QUOTATION_LOADER,
      DRAFT_QUOTATIONS_DETAILS_LOADER,
    },
    dispatchLoader,
  ] = useLoaderContextValue()
  const [activeTab, setActiveTab] = useState(PKG_DETAILS_TAB[currActiveTab])
  const history = useHistory()
  const [, updateDraftQuoteReq] = useUpdateDraftQuote()
  const [{ draftQuotationsDetailsData = {} }, getDraftQuoteDetailsReq] = useGetDraftQuoteDetails()
  const pkgOptionRef = useRef()
  const updateDraftTimer = useRef()
  const savedDraftData = useRef({})
  const that = useRef({
    isSaveClick: false,
    draftId: getQueryParams('draftId'),
  })
  const discountRef = useRef({
    pkgCallTimer: '',
  })
  const [showPageLoader, setShowPageLoader] = useState(false)
  const [{ updateDraftQuotationStatus, draftQuotationsDetailsStatus, getPackageDetailStatus }] =
    useErrorContextValue()
  const { resetError } = useResetError()

  const policyCreationData = useRef({})
  const addBackEventListener = useBackButton()

  const isHardCopyChange = useRef(false)

  useEffect(() => {
    if (draftQuoteId) {
      getDraftQuoteDetailsReq({
        draftQuoteId,
      })
    }
  }, [getDraftQuoteDetailsReq, draftQuoteId])

  useEffect(() => {
    return () => {
      dispatchLoader(
        updateLoader({
          GET_PACKAGE_DETAIL_LOADER: undefined,
        })
      )
    }
  }, [dispatchLoader])

  const initialPkgReq = useCallback((policyDetails) => {
    if (policyDetails?.start_date && !checkValidateStartDate(policyDetails?.start_date)) {
      policyDetails.start_date = moment().format('YYYY-MM-DD')
    }
    return {
      pkgReqBody: {
        ...getPackagesReqBody(policyDetails),
        ...(policyDetails.addons_data || {}),
        ...getExtraVehicleData(policyDetails),
        discount: policyDetails.discount,
        purchase_type: policyDetails.purchase_type,
        provider_branch: policyDetails.provider_branch,
        add_on: policyDetails?.addons_data?.add_on || [],
      },
      draft_id: that.current.draftId,
      applicationData: policyDetails,
      isRenewalFlow: window.location.href.includes('renewal'),
      pkgCode: policyDetails.provider_package_code,
    }
  }, [])

  useEffect(() => {
    if (draftQuotationsDetailsData?.package_code) {
      const policyDetails = draftQuotationsDetailsData.policy_details
      policyCreationData.current = initialPkgReq(policyDetails)
      that.current.removeBackListener = addBackEventListener({
        section: 'package_insurance',
        subSection: 'package_details',
        draftId: draftQuotationsDetailsData.id,
      })
      getPkgDetailsReq({
        body: {
          ...policyCreationData?.current.pkgReqBody,
          ...(policyCreationData?.current?.applicationData?.category_name
            ? { category_name: policyCreationData?.current?.applicationData?.category_name }
            : {}),
          ...(policyCreationData?.current?.applicationData?.end_date
            ? { end_date: policyCreationData?.current?.applicationData?.end_date }
            : {}),
          ...(policyCreationData?.current?.applicationData?.year_based_package_type_map
            ? {
                year_based_package_type_map:
                  policyCreationData?.current?.applicationData?.year_based_package_type_map,
              }
            : {}),
        },
        packageCode: policyCreationData?.current.pkgCode,
      })
    }
  }, [draftQuotationsDetailsData, getPkgDetailsReq, initialPkgReq, addBackEventListener])

  useEffect(() => {
    if (updateDraftQuotationStatus === 'success') {
      if (isHardCopyChange.current) {
        isHardCopyChange.current = false
        if (draftQuoteId) {
          getDraftQuoteDetailsReq({ draftQuoteId })
        }
      }
      // show loader only when click on buy
      if (that.current.isSaveClick) {
        that.current.isSaveClick = false
        setShowQuoteConfirm(true)
      } else if (showPageLoader) {
        setShowPageLoader(false)
        that.current.removeBackListener()
        history.push({
          pathname: `/motor_vehicle/form/${draftQuoteId}`,
          state: {
            from: window.location.pathname,
          },
        })
      }
      resetError(['updateDraftQuotationStatus'])
    }

    if (draftQuotationsDetailsStatus === 'success' && draftQuotationsDetailsData?.id) {
      if (!checkValidateStartDate(draftQuotationsDetailsData?.policy_details?.start_date)) {
        ShowSnackbar.success({
          visible: true,
          text: LANG_STRINGS.policyStartDateHasBeenChangedToCurrent,
        })
      }
      resetError(['draftQuotationsDetailsStatus'])
    }
  }, [
    updateDraftQuotationStatus,
    showPageLoader,
    resetError,
    history,
    draftQuoteId,
    getPackageDetailStatus,
    draftQuotationsDetailsStatus,
    draftQuotationsDetailsData,
    getDraftQuoteDetailsReq,
  ])

  const handleSaveDraft = useCallback(
    (extraData = {}, timer) => {
      savedDraftData.current = {
        ...policyCreationData.current.applicationData,
        ...savedDraftData.current,
        ...extraData,
      }
      const policyPkgData = getFromLocalStorageData(POLICY_PKG_DATA)
      policyPkgData.applicationData = {
        ...savedDraftData.current,
      }
      setToLocalStorage(POLICY_PKG_DATA, policyPkgData)
      setEnableSave(true)
      if (updateDraftTimer.current) {
        clearTimeout(updateDraftTimer.current)
        updateDraftTimer.current = ''
      }
      if (that.current.isBuyClick) {
        setShowPageLoader(true)
      }
      updateDraftTimer.current = setTimeout(() => {
        // if its a buy then its moved to next page
        updateDraftQuoteReq({
          body: {
            section: that.current.isBuyClick ? 'insured_object' : 'package_insurance',
            sub_section: that.current.isBuyClick ? 'vehicle_object_details' : 'package_details',
            data: {
              ...savedDraftData.current,
              ev_variant: savedDraftData.current?.model_data?.ev_variant,
              brand_code: savedDraftData.current?.model_data?.brand_code,
            },
          },
          draftQuoteId,
        })
      }, timer || 3000)
    },
    [updateDraftQuoteReq, policyCreationData, draftQuoteId]
  )

  useEffect(() => {
    if (getPackageDetailData.code) {
      const body = {
        package_data: getPackageDetailData,
        add_ons_cat: getPackageDetailData.add_ons_cat,
      }
      handleSaveDraft(body, 1)
    }
  }, [getPackageDetailData, handleSaveDraft])

  useEffect(() => {
    if (savedAddonsData) {
      that.current.addonsMap = getAddonsMapFromCategory(savedAddonsData)
      that.current.savedAddonsData = { ...savedAddonsData }
      getPkgDetailsReq({
        body: {
          ...policyCreationData?.current.pkgReqBody,
          ...that.current.addonsMap,
          ...(policyCreationData?.current?.applicationData?.category_name
            ? { category_name: policyCreationData?.current?.applicationData?.category_name }
            : {}),
          ...(policyCreationData?.current?.applicationData?.year_based_package_type_map
            ? {
                year_based_package_type_map:
                  policyCreationData?.current?.applicationData?.year_based_package_type_map,
              }
            : {}),
        },
        packageCode: policyCreationData?.current.pkgCode,
      })
    }
  }, [savedAddonsData, getPkgDetailsReq])

  const handleSelectedTab = useCallback((tab) => {
    // handle the tab selected
    setActiveTab(tab)
  }, [])

  useEffect(() => {
    if (getPackageDetailStatus === 'success' && that.current.savedAddonsData) {
      const policyPkgData = getFromLocalStorageData(POLICY_PKG_DATA)
      policyPkgData.selectedAddon = {
        ...that.current.savedAddonsData,
      }
      setToLocalStorage(POLICY_PKG_DATA, policyPkgData)
      policyCreationData.current.applicationData.addons_data = {
        ...that.current.addonsMap,
      }
      policyCreationData.current.pkgReqBody = {
        ...policyCreationData.current.pkgReqBody,
        ...that.current.addonsMap,
      }
      handleSaveDraft(
        {
          addons_data: {
            ...that.current.addonsMap,
          },
        },
        0
      )
      delete that.current.savedAddonsData
      resetError(['getPackageDetailStatus'])
    }
  }, [resetError, getPackageDetailStatus, handleSaveDraft])

  useEffect(() => {
    if (getPackageDetailStatus === 'success' && discountRef.current.updateDiscount) {
      discountRef.current.updateDiscount = false
      handleSaveDraft(
        {
          discount: policyCreationData.current.pkgReqBody.discount,
          package_data: getPackageDetailData,
        },
        1
      )
      resetError(['getPackageDetailStatus'])
    }
  }, [getPackageDetailStatus, getPackageDetailData, handleSaveDraft, resetError])

  const handleBackClick = () => {
    if (isRedirected && redirectBackUrl) {
      history.push(redirectBackUrl)
    } else {
      history.push(`/motor_vehicle/packages/v2/${draftQuoteId}`)
    }
  }

  const isShowAddonReminderModal = useCallback(() => {
    return pkgOptionRef.current?.isShowAddonReminderModal()
  }, [pkgOptionRef])

  const handleShowAddonsModal = useCallback(
    (show) => {
      pkgOptionRef.current.showAddonsModal(show)
    },
    [pkgOptionRef]
  )

  const handleSaveClick = useCallback(() => {
    that.current.isSaveClick = true
    handleSaveDraft({}, 1)
  }, [handleSaveDraft])

  const handleBuyClick = useCallback(
    (data, timer) => {
      that.current.isBuyClick = !!timer
      handleSaveDraft(data, timer)
    },
    [handleSaveDraft]
  )

  const handleDiscountChange = ({ discount }) => {
    if (discountRef.current.pkgCallTimer) {
      clearTimeout(discountRef.current.pkgCallTimer)
    }
    discountRef.current.pkgCallTimer = setTimeout(() => {
      policyCreationData.current.pkgReqBody.discount = discount
      draftQuotationsDetailsData.policy_details.discount = discount
      clearTimeout(discountRef.current.pkgCallTimer)
      discountRef.current.updateDiscount = true
      getPkgDetailsReq({
        body: {
          ...policyCreationData?.current.pkgReqBody,
          ...that.current.addonsMap,
          ...(policyCreationData?.current?.applicationData?.category_name
            ? { category_name: policyCreationData?.current?.applicationData?.category_name }
            : {}),
          ...(policyCreationData?.current?.applicationData?.end_date
            ? { end_date: policyCreationData?.current?.applicationData?.end_date }
            : {}),
          ...(policyCreationData?.current?.applicationData?.year_based_package_type_map
            ? {
                year_based_package_type_map:
                  policyCreationData?.current?.applicationData?.year_based_package_type_map,
              }
            : {}),
        },
        packageCode: policyCreationData?.current.pkgCode,
      })
    }, 600)
  }

  const handleHardCopyChange = useCallback(() => {
    isHardCopyChange.current = true
  }, [])

  return (
    <Container
      title={LANG_STRINGS.insurancePkgDetail}
      // backBtnId='mobilPackageDetailStepBack_2'
      onClose={() => {
        history.replace('/dashboard')
        that.current.removeBackListener && that.current.removeBackListener()
        ShowSnackbar.success({ text: LANG_STRINGS.quotationSaveMsg })
      }}
      onBackClick={handleBackClick}
      onSaveClick={handleSaveClick}
      saveLoader={UPDATE_DRAFT_QUOTATION_LOADER}
      loader={
        GET_PACKAGE_DETAIL_LOADER ||
        CREATE_APPLICATION_LOADER ||
        DRAFT_QUOTATIONS_DETAILS_LOADER ||
        showPageLoader
      }
      disabledSave={!enableSave}
      showSaveIcon
      showCloseIcon
      hideGuardianInfo
      hideBottomTabs
    >
      {!isRedirected && (
        <PolicyStepsHeader
          stepsData={POLICY_STEPS}
          activeCount={2}
          prevActive={{
            1: true,
          }}
        />
      )}
      <PackageDetailsStyle>
        {getPackageDetailData.code && (
          <>
            <PackageItem
              key={getPackageDetailData.code}
              packageItem={{
                ...getPackageDetailData,
                premium: policyCreationData?.current?.applicationData?.premium,
              }}
              noCardClick
              purchaseType={policyCreationData.current.pkgReqBody.purchaseType}
              applicationData={getPackageDetailData}
            />
            <Tabs
              data={PKG_DETAILS_TAB}
              defaultTab={activeTab}
              onClick={handleSelectedTab}
              top="90px"
              isSticky
              fontSize="0.75em"
            />
            {activeTab.value === 'options' && (
              <PkgOptionSection
                ref={pkgOptionRef}
                pkg={getPackageDetailData}
                policyData={policyCreationData.current}
                benefits={getPackageDetailData?.benefit?.data}
                onSaveDraft={handleSaveDraft}
                onHardCopyChange={handleHardCopyChange}
              />
            )}
            {activeTab.value === 'benefit' && (
              <PackageBenefitSection benefits={getPackageDetailData?.benefit?.data} />
            )}
            {activeTab.value === 'terms' && <PackageTermsSection tnc={getPackageDetailData?.tnc} />}
            <PackageActionBtn
              pkg={getPackageDetailData}
              policyData={policyCreationData.current}
              history={history}
              onSaveDraft={handleBuyClick}
              onDiscountChange={handleDiscountChange}
              draftId={draftQuoteId}
              discountLoader={GET_PACKAGE_DETAIL_LOADER}
              showFinalCommissionWord
              yearBasedMapping={
                draftQuotationsDetailsData?.policy_details?.year_based_package_type_map
              }
              draftQuotationsDetailsData={draftQuotationsDetailsData}
              isRedirected={isRedirected}
              onRedirectBackClick={handleBackClick}
              showDiscountCtn={showDiscountCtn}
              isShowAddonReminderModal={isShowAddonReminderModal}
              showAddonsModal={handleShowAddonsModal}
            />
          </>
        )}
        {GET_PACKAGE_DETAIL_LOADER === false && !getPackageDetailData.code && (
          <PackageNotFound history={history} productCode={CAR_PROTECTION} />
        )}
        <QuoteSaveConfirmModal
          show={showQuoteConfirm}
          onClose={() => setShowQuoteConfirm(false)}
          page={`${LANG_STRINGS.mobil} Step 2`}
          message={LANG_STRINGS.quotationSaveMsg}
        />
      </PackageDetailsStyle>
    </Container>
  )
}

export default PackageDetailsContainer
