import { CustomText, Button } from '../../../../../components'
import { LANG_STRINGS } from '../../../../../lang'
import { PkgAddonsSectionStyle } from './index.style'
import { AgentColorPallette } from '../../../../../configs/colorPallete'
import { forwardRef, useCallback, useEffect, useImperativeHandle, useState } from 'react'
import MVPolicyAddonsModal from '../MVPolicyAddonsModal'
import { useSaveAddonsData } from '../../state/hooks/usePackages'
import SelectedPkgAddons from '../SelectedPkgAddons'
import { useErrorContextValue, useResetError } from '@pasarpolis/common-react-hooks'
import ShowSnackbar from '../../../../../components/ShowNotification'

const PkgAddonsSection = ({ pkg = {}, policyData = {} }, ref) => {
  // const [showAddons, setShowAddons] = useState(!!pkg?.add_ons_cat?.length)
  const [showAddonsModal, setShowAddonsModal] = useState(false)
  const [, addonsRequest] = useSaveAddonsData()
  const [{ getPackageDetailStatus, getPackageDetailErrorData }] = useErrorContextValue()
  const { resetError } = useResetError()

  useImperativeHandle(
    ref,
    () => ({
      isShowAddonReminderModal: () => {
        return pkg?.add_ons_cat?.length <= 0
      },
      showAddonsModal: (show) => setShowAddonsModal(show),
    }),
    [pkg, setShowAddonsModal]
  )

  useEffect(() => {
    if (getPackageDetailStatus && getPackageDetailStatus !== 'success') {
      ShowSnackbar.error({
        text: getPackageDetailStatus,
        visible: true,
      })
      if (getPackageDetailErrorData.error_code === 'PP-IS-PKGDETAILS-4004') {
        // TODO: need to handle error code corresponding state
      } else if (getPackageDetailErrorData.error_code === 'PP-IS-PKGDETAILS-4003') {
        // TODO: need to handle error code corresponding state
      }
      resetError(['getPackageDetailStatus', 'getPackageDetailErrorData'])
    } else if (getPackageDetailStatus === 'success') {
      setShowAddonsModal(false)
      resetError(['getPackageDetailStatus', 'getPackageDetailErrorData'])
    }
  }, [resetError, getPackageDetailStatus, getPackageDetailErrorData])

  const handleSubmit = useCallback(
    (addonsData) => {
      // if (isEmpty(addonsData)) {
      //   setShowAddons(false)
      // }
      addonsRequest(addonsData)
    },
    [addonsRequest]
  )

  const handleShowAddon = useCallback(() => {
    setShowAddonsModal(true)
  }, [])

  const handleCloseAddonsModal = useCallback(() => {
    // close addons modal and also check if any addons exist then don't
    // switch off the button
    setShowAddonsModal(false)
  }, [])

  const policyDetail = {
    ...policyData.pkgReqBody,
    ...(policyData.applicationData?.purchase_type && {
      purchase_type: policyData.applicationData.purchase_type,
    }),
    ...(policyData.applicationData?.category_name && {
      category_name: policyData.applicationData.category_name,
    }),
    ...(policyData.applicationData?.year_based_package_type_map && {
      year_based_package_type_map: policyData.applicationData.year_based_package_type_map,
    }),
  }

  return (
    <PkgAddonsSectionStyle>
      {/* <Heading
        title={LANG_STRINGS.additionalProtection}
        className='heading-space'
        size='0.9rem'
      /> */}
      <CustomText color={AgentColorPallette.black} size="0.9em" bottom="0.5em" weight={700}>
        {LANG_STRINGS.additionalProtection}
      </CustomText>
      <CustomText color={AgentColorPallette.blackGrey} size="0.8rem">
        {LANG_STRINGS.additionalProtectionCta}
      </CustomText>
      {pkg?.add_ons_cat?.length > 0 && (
        <SelectedPkgAddons addonsData={pkg.add_ons_cat} policyDetail={policyDetail} />
      )}
      <Button className="add-button" onClick={handleShowAddon}>
        Tambah Perlindungan
      </Button>
      {pkg?.add_ons_cat?.length > 0 && (
        <Button
          className="remove-button"
          onClick={() => {
            if (pkg?.add_ons_cat?.length > 0) {
              addonsRequest({})
            }
          }}
        >
          Batal
        </Button>
      )}
      {showAddonsModal && (
        <MVPolicyAddonsModal
          showModal={showAddonsModal}
          onClose={handleCloseAddonsModal}
          onSubmit={handleSubmit}
          productCode={pkg.code}
          applicationData={{
            ...pkg,
            policy_detail: policyDetail,
          }}
        />
      )}
    </PkgAddonsSectionStyle>
  )
}

export default forwardRef(PkgAddonsSection)
