import moment from 'moment'
import { POLICY_PKG_REQ_DATA } from '../constants/cookies'
import { getFromLocalStorageData } from './localstorage'

export const mapOnlineDataToOffline = () => {
  const data = getFromLocalStorageData(POLICY_PKG_REQ_DATA)
  return {
    code: data.code || data.product_code,
    accessories: data.accessories,
    addons: data.addons,
    brand: data.brand,
    brand_data: data.brand_data,
    isModificationChecked: !!data?.accessories?.length,
    model: data.model,
    model_data: data.model_data,
    ...(data.model_data || {}),
    packageType: data.package_type,
    policyPeriod: {
      startDate: moment(data.start_date, 'YYYY-MM-DD').format('DD/MM/yyyy'),
      endDate: moment(data.start_date, 'YYYY-MM-DD').add(1, 'year').format('DD/MM/yyyy'),
      selectedTimePeriod: 1
    },
    region_code: data.region_code,
    vehicleUse: data.usage,
    transportationType: data.vehicle_type,
    vehicle_plate_no: data.vehicle_plate_no,
    vehicle_sum_insured: data.vehicle_sum_insured,
    year: data.year,
    year_data: data.year_data || (data.year ? { year: data.year } : null)
  }
}
